#include <stdio.h>

int main(void) {
    // 1. Storage & Variable Declaration
    float price, tax, total;

    // 2. Input
    printf("Enter product price (KES): ");
    scanf("%f", &price);

    // 3. Processing
    tax = price * 0.16f; // 16% VAT
    total = price + tax;

    // 4. Output
    printf("Base Price: KES %.2f\n", price);
    printf("VAT (16%%):  KES %.2f\n", tax);
    printf("Final Due:  KES %.2f\n", total);

    return 0; // Success exit status
}

