#include <stdio.h>     // Link Section

#define PASS_MARK 50   // Definition Section

int validateScore(int score); // Global Prototype

int main(void) {              // Main Entrypoint
    int userScore = 75;
    if (validateScore(userScore)) {
        printf("Student Passed!\n");
    }
    return 0;                 // 0 = Normal termination
}

int validateScore(int score) { // Subprogram Section
    return score >= PASS_MARK;
}

