#include <stdio.h>

int main(void) {
    int marks = 15;
    int total = 20;

    // BAD: Integer division discards decimal remainder!
    float wrongPercent = marks / total * 100; // Evaluates 0 * 100 = 0.00%

    // GOOD: Explicit typecasting forces floating point division
    float rightPercent = ((float)marks / total) * 100; // Evaluates 0.75 * 100 = 75.00%

    printf("Wrong: %.2f%%\n", wrongPercent);
    printf("Right: %.2f%%\n", rightPercent);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a = 5, b = 5;

    int res1 = ++a * 2; // a becomes 6, then 6 * 2 = 12
    int res2 = b++ * 2; // 5 * 2 = 10, then b becomes 6

    printf("Prefix result:  %d, a is %d\n", res1, a);
    printf("Postfix result: %d, b is %d\n", res2, b);
    return 0;
}
